-- Private, tenant-scoped enrichment. Counts and minimal fields share one MVCC statement.
CREATE TABLE IF NOT EXISTS public.live_lineup_audience_versions (
  rep_id uuid PRIMARY KEY REFERENCES public.reps(id) ON DELETE CASCADE,
  version bigint NOT NULL DEFAULT 0 CHECK (version >= 0)
);
ALTER TABLE public.live_lineup_audience_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY live_lineup_audience_version_owner ON public.live_lineup_audience_versions
  FOR SELECT TO authenticated USING (rep_id IN (SELECT id FROM public.reps WHERE auth_user_id = auth.uid()));
GRANT SELECT ON public.live_lineup_audience_versions TO authenticated;
GRANT ALL ON public.live_lineup_audience_versions TO service_role;

