CREATE OR REPLACE FUNCTION public.live_lineup_audience_name_key(value text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path = public AS $$
  SELECT public.live_lineup_casefold(btrim(regexp_replace(translate(value,
    chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279),
    repeat(' ',19)), '[[:space:]]+', ' ', 'g')))
$$;
CREATE INDEX IF NOT EXISTS live_lineup_audience_exact_name ON public.customer_audience
  (rep_id, public.live_lineup_audience_name_key(name));

CREATE OR REPLACE FUNCTION public.live_lineup_audience_changed() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF TG_OP <> 'INSERT' AND EXISTS (SELECT 1 FROM public.reps WHERE id=OLD.rep_id) THEN
    INSERT INTO public.live_lineup_audience_versions(rep_id,version) VALUES(OLD.rep_id,1)
      ON CONFLICT(rep_id) DO UPDATE SET version=live_lineup_audience_versions.version+1;
  END IF;
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.rep_id <> OLD.rep_id) THEN
    INSERT INTO public.live_lineup_audience_versions(rep_id,version) VALUES(NEW.rep_id,1)
      ON CONFLICT(rep_id) DO UPDATE SET version=live_lineup_audience_versions.version+1;
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER live_lineup_audience_version_changed AFTER INSERT OR UPDATE OR DELETE ON public.customer_audience
  FOR EACH ROW EXECUTE FUNCTION public.live_lineup_audience_changed();

CREATE OR REPLACE FUNCTION public.live_lineup_match_audience(p_rep_id uuid, p_names text[]) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public SET statement_timeout = '2000ms' AS $$
  WITH requested AS (
    SELECT DISTINCT name AS key, public.live_lineup_audience_name_key(name) AS normalized FROM unnest(p_names) name
    WHERE cardinality(p_names) <= 2000 AND length(name) <= 201 AND btrim(name) <> ''
  ), matches AS (
    SELECT r.key, count(a.id) AS count,
      CASE WHEN count(a.id)=1 THEN min(a.birthday_month) END AS month,
      CASE WHEN count(a.id)=1 THEN min(a.birthday_day) END AS day,
      CASE WHEN count(a.id)=1 THEN min(a.favorite_gem_or_stone) END AS gem,
      CASE WHEN count(a.id)=1 THEN min(a.favorite_material) END AS material,
      CASE WHEN count(a.id)=1 THEN min(a.favorite_cut) END AS cut,
      CASE WHEN count(a.id)=1 THEN min(a.favorite_collection) END AS collection
    FROM requested r LEFT JOIN public.customer_audience a
      ON a.rep_id=p_rep_id AND public.live_lineup_audience_name_key(a.name)=r.normalized
    GROUP BY r.key
  ) SELECT jsonb_build_object('version',coalesce((SELECT version FROM public.live_lineup_audience_versions WHERE rep_id=p_rep_id),0)::text,
    'matches',coalesce((SELECT jsonb_agg(to_jsonb(matches)) FROM matches),'[]'::jsonb))
$$;
REVOKE ALL ON FUNCTION public.live_lineup_match_audience(uuid,text[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.live_lineup_match_audience(uuid,text[]) TO service_role;
REVOKE ALL ON FUNCTION public.live_lineup_audience_changed() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.live_lineup_audience_versions;
  END IF;
END $$;
